// NB-05 · spec: .qa/e2e/specs/nearby.md 1.5 · две роли · меняет данные → в finally оба false.
import { test, expect } from '../../fixtures';
import { openRole, turnOff, meetPair, tapWhenTop, card, NAME } from './nearby-helpers';

test.use({ browserName: 'webkit' });

const minutes = (hhmm: string) => { const [h, m] = hhmm.split(':').map(Number); return h * 60 + m; };

test.describe('היו כאן — משתמשים שהיו בקרבת מקום', () => {
  test.describe.configure({ timeout: 180_000 });
  test('маркер места фильтрует лист — «ליד <место>» и «אדם אחד · HH:MM–HH:MM» в прямом порядке @iphone @data (#67c751)', async ({ browser }) => {
    const reg1 = await openRole(browser, 'reg1');
    const reg2 = await openRole(browser, 'reg2');
    try {
      await meetPair(reg1, reg2);
      const p = reg1.page;
      // Маркер места: кнопка «<число> <название>», не пин «אני». Название приходит из OSM — ждём, пока появится.
      // Иконка маркера Leaflet — div 0×0 с title=<место>; тапаем по её видимому содержимому.
      const marker = p.getByRole('button', { name: /^\d+ (?!מקום \d)/ }).first();
      await expect(marker).toBeAttached();
      await expect(marker).toHaveAttribute('title', /\S/);
      const label = (await marker.getAttribute('title')) ?? '';
      await tapWhenTop(p, marker.locator('*').filter({ visible: true }).first());
      const heading = p.getByText(/^ליד /).first();
      await expect(heading).toBeVisible();
      const place = label.trim();
      if (place) await expect(heading).toContainText(place);
      const range = p.getByText(/אדם אחד · \d{2}:\d{2}–\d{2}:\d{2}/);
      await expect(range).toBeVisible();
      const [, from, to] = (await range.innerText()).match(/(\d{2}:\d{2})–(\d{2}:\d{2})/)!;
      expect(minutes(from), `диапазон ${from}–${to} в прямом порядке`).toBeLessThanOrEqual(minutes(to));
      await expect(card(p, NAME.reg2)).toBeVisible();
    } finally {
      await turnOff(reg1);
      await turnOff(reg2);
      await reg1.ctx.close();
      await reg2.ctx.close();
    }
  });
});
